// Üretilen dosya: tool/ozgun/uret.py. Tarih · Yazı, kâğıt, matbaa, kütüphaneler, medreseler ve üniversiteler tarihi (çivi yazısı, parşömen, İskenderiye, Beytülhikme, Nizamiye, Sahn-ı Seman, ilk üniversiteler) (kolay).
const ozHistory17Kolay = <(String, String, List<String>, String)>[
  ('Tarihte bilinen ilk yazı sistemi olan çivi yazısını icat eden Mezopotamya uygarlığı hangisidir?', 'Sümerler', ['Babil Krallığı', 'Asur İmparatorluğu', 'Akad İmparatorluğu'], 'Tarihte bilinen ilk yazı sistemi MÖ 3200 civarında Güney Mezopotamya\'da Sümerler tarafından icat edilmiştir.'),
  ('Sümerlerde çivi yazısının ortaya çıkmasındaki en temel toplumsal ve ekonomik ihtiyaç aşağıdakilerden hangisidir?', 'Tapınak depolarına giren ve çıkan tarımsal ürünlerin kaydını tutmak', ['Komşu krallıklarla yapılan barış antlaşmalarını kalıcı hale getirmek', 'Hükümdarların askeri seferlerini gelecek kuşaklara edebi dille aktarmak', 'Gökyüzü gözlemlerine dayalı dini kehanet metinlerini halka duyurmak'], 'Sümerlerde ziggurat adı verilen tapınak ekonomisinde ürünlerin toplanması ve dağıtılması sürecini kayıt altına alma ihtiyacı yazıyı doğurmuştur.'),
  ('Sümerlerin üzerine çivi yazısı kazıdıkları veya bastırdıkları temel yazı malzemesi nedir?', 'Kil tablet', ['Papirüs rulosu', 'Koyun derisi parşömen', 'İpek kumaş levha'], 'Mezopotamya\'da Dicle ve Fırat nehirlerinin getirdiği alüvyonlu kil bol bulunduğu için ıslak kil tabletler temel yazı malzemesi olmuştur.'),
  ('Antik Çağ\'ın en büyük çivi yazılı kil tablet koleksiyonu olan Ninova Kütüphanesi hangi hükümdar tarafından kurulmuştur?', 'Asurbanipal', ['Hammurabi', 'II. Sargon', 'Nebukadnezar'], 'Asur Kralı Asurbanipal, başkent Ninova\'da Mezopotamya\'nın edebi, bilimsel ve dini mirasını toplayan dev bir kil tablet kütüphanesi kurmuştur.'),
  ('Antik Mısır\'da tapınak duvarlarına ve anıtlara kazınan kutsal resim yazısına ne ad verilir?', 'Hiyeroglif', ['Çivi yazısı', 'Göktürk alfabesi', 'Kiril alfabesi'], 'Yunanca "kutsal oyma/kazıma" anlamına gelen hiyeroglif, Antik Mısır\'ın anıtsal resim yazısı sistemidir.'),
  ('Mısır hiyerogliflerinin çözülmesini sağlayan ve üzerinde üç farklı yazı sistemi bulunan ünlü arkeolojik eser hangisidir?', 'Rosetta Taşı', ['Hammurabi Steli', 'Kadeş Antlaşması Tableti', 'Palermo Taşı'], '1799 yılında Reşid (Rosetta) kasabasında bulunan bazalt taş, aynı fermanı üç farklı yazıyla içerdiği için hiyerogliflerin anahtarı olmuştur.'),
  ('1822 yılında Rosetta Taşı üzerindeki metinleri karşılaştırarak Mısır hiyerogliflerini kesin olarak çözen Fransız dilbilimci kimdir?', 'Jean-François Champollion', ['Thomas Young', 'Auguste Mariette', 'Howard Carter'], 'Jean-François Champollion, Kıpti dili bilgisinden ve kral adlarını çevreleyen kartuşlardan yararlanarak 1822\'de hiyeroglif sistemini çözmüştür.'),
  ('Antik Mısırlıların Nil Nehri kıyılarında yetişen kamış benzeri su bitkisinin gövdesinden ürettikleri yazı malzemesi hangisidir?', 'Papirüs', ['Parşömen', 'Tirşe', 'Mulberry kâğıdı'], 'Cyperus papyrus bitkisinin gövde özünden üretilen papirüs, Antik Akdeniz dünyasının en yaygın yazı malzemesi olmuştur.'),
  ('Fenike alfabesi toplam kaç harften oluşmaktaydı ve bu harflerin ses özelliği neydi?', 'Tamamı ünsüz (sessiz) sesleri gösteren 22 harf', ['Ünlü ve ünsüz sesleri eşit gösteren 29 harf', 'Her biri bir heceyi karşılayan 60 işaret', 'Yalnızca uzun ünlü sesleri belirten 14 harf'], 'Kuzeybatı Sami dillerinden olan Fenikecede kelimelerin kök anlamını ünsüzler taşıdığı için Fenike alfabesi yalnızca 22 ünsüz harften (ebced) oluşurdu.'),
  ('Antik Yunanların MÖ 8. yüzyılda Fenikelilerden aldıkları alfabeye yaptıkları en önemli yapısal yenilik aşağıdakilerden hangisidir?', 'Yunancada kullanılmayan bazı Sami ünsüz harflerini ünlü (sesli) harflere dönüştürmeleri', ['Harf sayısını 22\'den 50\'ye çıkararak her hece için ayrı bir sembol icat etmeleri', 'Kelimeler arasına modern noktalama işaretlerini ve büyük-küçük harf ayrımını getirmeleri', 'Yazıyı soldan sağa değil yalnızca yukarıdan aşağıya doğru dikey sütunlarla yazmaları'], 'Hint-Avrupa dili olan Yunancada ünlü sesler kelime anlamı için hayati olduğundan Yunanlar alef, he, yod, ayin gibi harfleri A, E, I, O sesli harflerine dönüştürerek ilk tam alfabeyi yaratmıştır.'),
  ('Yunan alfabesinin ilk iki harfi olan "Alfa" ve "Beta"nın isimleri hangi dildeki anlamlı kelimelerden türemiştir?', 'Fenike/Sami dillerindeki "alef" (öküz) ve "bet" (ev) kelimelerinden', ['Mısır dilindeki "amon" (güneş) ve "ba" (ruh) kelimelerinden', 'Sümercedeki "an" (gök) ve "ki" (yer) kelimelerinden', 'Latincedeki "aqua" (su) ve "bellis" (güzel) kelimelerinden'], 'Yunancada tek başına anlamı olmayan "alfa" ve "beta" adları, Fenikelilerin öküz (alef) ve ev (bet) anlamındaki harf isimlerinin ödünç alınmasıyla oluşmuş ve "alfabe" kelimesini doğurmuştur.'),
  ('Antik Roma\'da okul öğrencilerinin alıştırma yapmak ve günlük not tutmak için kullandıkları, üzeri ince balmumu kaplı ahşap levhalara ne denirdi?', 'Balmumu tablet', ['Papirüs kodeks', 'Kil silindir', 'İpek parşömen'], 'Çerçeveli ahşap levhaların çukur yüzeyine dökülen balmumu, ucu sivri stylus ile yazılıp düz arka ucuyla kolayca silinebildiği için müsvette ve okul defteri olarak kullanılırdı.'),
  ('Mısır hiyeroglifleri hangi tarihsel gelişmenin ardından tapınaklardaki son uzman rahiplerin de ölmesiyle bin yılı aşkın süre okunamaz hale gelmiştir?', 'Roma İmparatorluğu\'nda Hristiyanlığın resmi din olması ve pagan tapınaklarının kapatılması', ['Büyük İskender\'in Mısır\'ı fethederek İskenderiye kentini kurması', 'Pers Kralı Kambises\'in Mısır\'daki tüm papirüs kütüphanelerini yakması', 'Fenikelilerin Akdeniz ticaretini ele geçirip Mısır limanlarını ablukaya alması'], 'MS 4. yüzyıl sonunda Roma\'nın pagan tapınaklarını kapatması ve Kıpti Hristiyanlığın Yunan tabanlı Kıpti alfabesine geçmesiyle son hiyeroglif yazıt (Philae, MS 394) sonrası gelenek kopmuştur.'),
  ('Sümerlerin icat ettiği çivi yazısını kendi Sami dillerine uyarlayarak Mezopotamya\'da geniş bir coğrafyaya yayan ilk imparatorluk hangisidir?', 'Akadlar', ['Frigler', 'Lidyalılar', 'Medler'], 'Sargon önderliğinde kurulan Akad İmparatorluğu, Sümer çivi yazısını Doğu Sami dili olan Akadcaya uyarlayarak sistemin tüm Mezopotamya\'da yayılmasını sağlamıştır.'),
  ('Antik Mısır toplumunda kâtiplik mesleğinin yüksek saygınlık görmesinin ve ayrıcalıklı bir statü sağlamasının temel nedeni nedir?', 'Karmaşık hiyeroglif ve hiyeratik yazıyı okuyup yazabilenlerin devlet yönetiminde vazgeçilmez olması', ['Kâtiplerin yalnızca kraliyet ailesinin en büyük erkek çocukları arasından seçilmesi', 'Tapınaklardaki tüm altın madenlerinin mülkiyetinin doğrudan kâtiplere ait olması', 'Kâtiplerin savaşlarda ordunun en önünde çarpışan seçkin generaller olması'], 'Yüzlerce işaretten oluşan Mısır yazı sistemini öğrenmek uzun eğitim gerektirdiğinden, vergi toplama, hukuk ve bürokrasi tamamen okuryazar kâtip sınıfına dayanıyordu.'),
  ('Küçükbaş hayvanların kürek kemikleri, taş parçaları veya kırık çanak çömlek parçaları üzerine mürekkeple ya da kazınarak yazılan kısa günlük belgelere Antik Çağ\'da ne ad verilirdi?', 'Ostrakon', ['Kodeks', 'Ferman', 'Minyatür'], 'Papirüs pahalı olduğunda Antik Mısır ve Yunan dünyasında kırık seramik ve kireçtaşı parçaları (ostrakon; çoğulu ostraka) not, makbuz ve oylama pusulası olarak yaygın biçimde kullanılmıştır.'),
  ('Antik Mısır ve Mezopotamya\'da kâtiplerin yazı yazarken kamış kalemlerini, su kaplarını ve katı mürekkep kalıplarını bir arada taşıdıkları ahşap veya fildişi araca ne denirdi?', 'Kâtip paleti', ['Silindir mühür', 'Usturlap', 'Abaküs'], 'Özellikle Mısırlı kâtipler, üzerinde siyah ve kırmızı kuru mürekkep yuvaları ile kamış fırça haznesi bulunan dikdörtgen kâtip paletlerini yanlarında taşırlardı.'),
  ('Antik Çağ\'da keçi, koyun veya dana derisinin özel işlemlerle inceltilip pürüzsüzleştirilmesiyle üretilen ve adını Anadolu\'daki bir antik kentten alan yazı malzemesi hangisidir?', 'Parşömen (Bergama kâğıdı)', ['Papirüs (Nil kâğıdı)', 'Abaka lifi kâğıdı', 'Pişmiş kil levha'], 'Latince "charta pergamena" (Bergama kâğıdı) adından türeyen parşömen, küçükbaş ve büyükbaş hayvan derilerinin işlenmesiyle elde edilen dayanıklı yazı malzemesidir.'),
  ('Parşömen üretiminin gelişmesi ve kitap malzemesi olarak ün kazanması Batı Anadolu\'daki hangi Helenistik krallığın başkentiyle özdeşleşmiştir?', 'Bergama (Pergamon) Krallığı', ['Bitinya Krallığı', 'Pontus Krallığı', 'Kommagene Krallığı'], 'Attalos Hanedanı yönetimindeki Pergamon (Bergama), İskenderiye ile rekabet eden büyük kütüphanesi ve yüksek kaliteli deri işleme (parşömen) üretimiyle tanınmıştır.'),
  ('Katlanmış parşömen veya kâğıt formalarının sırt kısmından birbirine dikilip iki kapak arasına alınmasıyla oluşturulan ve bugünkü basılı kitapların doğrudan biçimsel atası olan form hangisidir?', 'Kodeks', ['Rulo', 'Silindir mühür', 'Taş stel'], 'Roma İmparatorluğu döneminde rulo formunun yerini almaya başlayan kodeks, sayfaları çevrilebilen modern ciltli kitap formudur.'),
  ('Bitkisel liflerin su içinde dövülüp hamur haline getirilmesi ve ince elekler üzerinde süzülerek kurutulmasıyla üretilen gerçek kâğıt ilk kez hangi uygarlıkta icat edilmiştir?', 'Çin', ['Mısır', 'Babil', 'Roma'], 'Gerçek kâğıt, MÖ 2. yüzyıldan itibaren erken örnekleri görülmekle birlikte MS 105 yılında Han Hanedanı dönemi Çin\'inde standart üretim tekniğine kavuşmuştur.'),
  ('Çin\'in yüzyıllarca sır gibi sakladığı kâğıt üretim teknolojisinin Orta Asya ve İslam dünyasına geçmesine zemin hazırlayan 751 yılındaki savaş hangisidir?', 'Talas Savaşı', ['Kadisiye Savaşı', 'Malazgirt Savaşı', 'Nihavend Savaşı'], '751 yılında Abbasi orduları ile Karluk Türklerinin Çin\'in Tang Hanedanı ordusunu yendiği Talas Savaşı sonrasında esir alınan Çinli ustalar aracılığıyla kâğıt yapımı Semerkant\'ta yayılmıştır.'),
  ('8. yüzyılın ikinci yarısından itibaren İslam dünyasının en kaliteli kâğıt üretim merkezi haline gelen ve ürettiği dayanıklı, parlak kâğıtlarla yüzyıllarca ün kazanan Orta Asya kenti hangisidir?', 'Semerkant', ['Kurtuba', 'Şam', 'Kahire'], 'Talas Savaşı\'nın ardından kurulan imalathanelerle Semerkant, keten ve kenevir paçavralarından üretilen üstün kaliteli "Semerkant kâğıdı" ile Doğu ve Batı\'da standart belirlemiştir.'),
  ('İslam medeniyetinde 8. ve 13. yüzyıllar arasındaki Bilim ve Felsefe Altın Çağı\'nda Beytülhikme gibi merkezlerde yüz binlerce ciltlik kütüphanelerin kurulabilmesini doğrudan kolaylaştıran maddi etken nedir?', 'Semerkant ve Bağdat\'tan yayılan kâğıt üretimi sayesinde kitap maliyetinin parşömene göre büyük ölçüde düşmesi', ['Gutenberg matbaasının 8. yüzyılda Bağdat\'ta kurularak günde binlerce kitap basması', 'Mısır\'dan bedelsiz olarak milyonlarca ton kil tablet getirtilmesi', 'Tüm çeviri eserlerin taş anıtlar üzerine kazınarak meydanlarda sergilenmesi'], 'Bir tek Kuran veya bilim külliyatı için yüzlerce koyun derisi (parşömen) gerekirken, kâğıt değirmenleri kitap üretimini hızlandırıp ucuzlatarak "verrâk" (kitap çoğaltıcı/satıcı) çarşılarını doğurmuştur.'),
  ('Orta Çağ Avrupa manastırlarında rahiplerin el yazması kitapları kopyalamak, resimlemek ve ciltlemek için özel olarak ayrılmış aydınlık çalışma odalarına ne ad verilirdi?', 'Scriptorium (yazıhane)', ['Refectorium (yemekhane)', 'Dormitorium (yatakhane)', 'Herbarium (bitki bahçesi)'], 'Latince "yazı yazılan yer" anlamındaki scriptorium, Orta Çağ boyunca klasik antik eserlerin ve dini kitapların rahiplerce elle çoğaltıldığı manastır atölyeleridir.'),
  ('Matbaacılık tarihinde ahşap blok baskı ve hareketli harf baskı tekniklerinin en erken örnekleri hangi coğrafyada ortaya çıkmıştır?', 'Doğu Asya\'da (Çin ve Kore)', ['Batı Avrupa\'da (Almanya ve Hollanda)', 'Güney Amerika\'da (İnka ve Maya)', 'Kuzey Afrika\'da (Mısır ve Tunus)'], 'Avrupa\'dan yüzyıllar önce Çin\'de ahşap kalıp (ksilografi) ve pişmiş kil hareketli harfler, Kore\'de ise dökme metal hareketli harfler kullanılmıştır.'),
  ('1450\'li yıllarda Avrupa\'da hareketli metal harfli baskı makinesini (matbaayı) geliştirerek bilgi ve kültür tarihinde devrim yaratan Alman mucit kimdir?', 'Johannes Gutenberg', ['Martin Luther', 'Desiderius Erasmus', 'William Caxton'], 'Aslen kuyumcu ve maden ustası olan Johannes Gutenberg, Almanya\'nın Mainz kentinde hareketli metal harf dökümü, yağ bazlı mürekkep ve vidalı baskı presini birleştirerek modern matbaayı kurmuştur.'),
  ('Johannes Gutenberg\'in matbaa sistemini kurup ilk büyük eserlerini bastığı Almanya kenti aşağıdakilerden hangisidir?', 'Mainz', ['Berlin', 'Münih', 'Hamburg'], 'Gutenberg teknik deneylerini Strazburg\'da başlatmış, ancak olgunlaşmış matbaa atölyesini kurup ünlü 42 Satırlık İncil\'i yaklaşık 1455\'te Mainz kentinde basmıştır.'),
  ('Gutenberg\'in 1455 civarında Mainz\'da bastığı ve her sütunundaki satır sayısıyla da anılan Batı dünyasının ilk büyük matbaa kitabı hangisidir?', 'Gutenberg İncili', ['Nürnberg Kroniği', 'İlahi Komedya', 'Canterbury Hikâyeleri'], 'Latince Vulgata metnini içeren ve her sayfasında 42 satırlık iki sütun bulunan "42 Satırlık İncil", yaklaşık 180 nüsha (çoğu kâğıt, bir kısmı parşömen üzerine) basılmıştır.'),
  ('Osmanlı İmparatorluğu\'nda 1727 yılında (Lale Devri\'nde) Said Efendi ile birlikte Türkçe-Arapça harfli ilk Türk Müslüman matbaasını kuran devlet adamı ve bilgin kimdir?', 'İbrahim Müteferrika', ['Kâtip Çelebi', 'Evliya Çelebi', 'Ali Kuşçu'], 'Macar asıllı Osmanlı aydın ve diplomatı İbrahim Müteferrika, Yirmisekiz Çelebizade Said Efendi\'nin desteğiyle 1727\'de Darüttıbaati\'l-Amire niteliğindeki ilk Türk matbaasını kurmuştur.'),
  ('Bir müzede sergilenen dört farklı tarihi belgenin kronolojik olarak en eskiden en yeniye doğru malzeme ve teknoloji sıralaması aşağıdakilerden hangisinde doğru verilmiştir?', 'Sümer kil tableti - Mısır papirüs rulosu - Semerkant kâğıt kodeksi - Gutenberg matbaa baskısı', ['Mısır papirüs rulosu - Sümer kil tableti - Gutenberg matbaa baskısı - Semerkant kâğıt kodeksi', 'Sümer kil tableti - Semerkant kâğıt kodeksi - Mısır papirüs rulosu - Gutenberg matbaa baskısı', 'Bergama parşömen kodeksi - Sümer kil tableti - Mısır papirüs rulosu - Semerkant kâğıt kodeksi'], 'Sümer kil tableti (MÖ 3200\'ler), Mısır papirüs rulosu (MÖ 3000\'ler ve sonrası), Semerkant kâğıt kodeksi (MS 8. yy ve sonrası), Gutenberg matbaası (MS 1450\'ler) kronolojik sırayı oluşturur.'),
  ('İslam ve Osmanlı kitap sanatlarında el yazması kitapların sayfa kenarlarını altın tozu (varak) ve toprak boyalarla bitkisel/geometrik motiflerle bezeme sanatına ne ad verilir?', 'Tezhip', ['Ebru', 'Hüsnühat', 'Hakkâklık'], 'Arapça "zeheb" (altın) kökünden gelen tezhip, "altınlama" demektir ve el yazması kodekslerin özellikle ilk sayfalarını (serlevha ve zahriye) süsleyen geleneksel kitap sanatıdır.'),
  ('Gutenberg\'in matbaasında bir sayfanın baskısı tamamlandıktan sonra dizilmiş metal harflerin sökülüp harf kasalarına geri dağıtılmasının sağladığı temel ekonomik avantaj nedir?', 'Aynı metal harflerin defalarca farklı kitap ve sayfaların dizgisinde yeniden kullanılabilmesi', ['Kullanılmış metal harflerin kâğıt hamuruna karıştırılarak mürekkep tasarrufu sağlaması', 'Her kitap baskısından sonra harflerin eritilip sikke olarak piyasaya sürülmesi', 'Harflerin sökülmesiyle baskı makinesinin kendiliğinden temizlenip yağlanması'], 'Ahşap blok baskıda oyulan sayfa kalıbı yalnızca o tek sayfa için işe yararken, "hareketli" metal harfler baskı bitince dağıtılıp yeni sayfaların dizgisinde yüzlerce kez kullanılabiliyordu.'),
  ('Matbaacılıkta tek tek metal harflerin kelime ve satır oluşturacak şekilde kumpas adı verilen el aletinde yan yana getirilip sayfa kalıbına yerleştirilmesi işlemine ne ad verilir?', 'Dizgi (mürettiplik)', ['Ciltleme (mücellitlik)', 'Tabaklama (debbağlık)', 'Aharlama (perdahçılık)'], 'Harf kasasından metal harfleri seçip satır ve sayfa düzenine yerleştiren ustaya "dizgici" (eski terimle mürettip), yapılan işleme de "dizgi" denir.'),
  ('Antik Mezopotamya\'da bilinen ilk sistemli kütüphaneyi başkent Ninova\'da kuran Asur kralı kimdir?', 'Asurbanipal', ['Hammurabi', 'II. Sargon', 'II. Nebukadnezar'], 'Asur Kralı Asurbanipal, MÖ 7. yüzyılda Ninova\'da binlerce kil tableti bir araya getirerek bilinen ilk sistemli kütüphaneyi kurmuştur.'),
  ('Ninova\'daki Asurbanipal Kütüphanesi\'nde korunan metinler hangi yazı sistemiyle ve hangi malzeme üzerine yazılmıştır?', 'Çivi yazısıyla kil tabletler üzerine', ['Hiyeroglif yazıyla papirüs ruloları üzerine', 'Fenike alfabesiyle parşömen yapraklar üzerine', 'Arami harfleriyle ceylan derisi üzerine'], 'Asurbanipal Kütüphanesi\'ndeki eserler Mezopotamya geleneğine uygun olarak çivi yazısıyla kil tabletler üzerine kaydedilmiştir.'),
  ('Antik Çağ\'ın en büyük bilim ve kültür merkezi kabul edilen İskenderiye Kütüphanesi hangi hanedan döneminde kurulmuştur?', 'Ptolemaios Hanedanı', ['Seleukos İmparatorluğu', 'Antigonos Hanedanı', 'Ahameniş İmparatorluğu'], 'Büyük İskender\'in ölümünden sonra Mısır\'da kurulan Helenistik Ptolemaios (Batlamyus) Hanedanı kütüphaneyi inşa etmiştir.'),
  ('İskenderiye Kütüphanesi\'nde eserlerin yazıldığı temel yazı malzemesi aşağıdakilerden hangisiydi?', 'Papirüs ruloları', ['Pişmiş kil tabletler', 'İpek kumaş tomarları', 'Bakır ve tunç levhalar'], 'Nil Deltası\'nda bolca yetişen papirüs bitkisinden üretilen rulolar İskenderiye Kütüphanesi\'nin ana malzemesiydi.'),
  ('Helenistik Dönem\'de İskenderiye Kütüphanesi ile büyük bir rekabete giren Anadolu\'daki ünlü kütüphane hangi antik kentte kurulmuştur?', 'Bergama', ['Miletos', 'Sardes', 'Halikarnassos'], 'Pergamon (Bergama) Krallığı başkenti Bergama\'da İskenderiye ile yarışan yaklaşık iki yüz bin ruloluk bir kütüphane kurmuştur.'),
  ('Bergama Kütüphanesi\'nin geliştirilmesiyle özdeşleşen ve keçi ya da koyun derisinin işlenmesiyle elde edilen dayanıklı yazı malzemesi hangisidir?', 'Parşömen', ['Papirüs', 'Kil tablet', 'İpek kağıt'], 'Adını Pergamon (Bergama) kentinden alan parşömen (charta pergamena), işlenmiş hayvan derisinden üretilen dayanıklı bir yazı malzemesidir.'),
  ('İslam medeniyetinde çeviri faaliyetlerinin ve bilimsel araştırmaların merkezi olan Beytülhikme hangi şehirde kurulmuştur?', 'Bağdat', ['Şam', 'Kahire', 'Kurtuba'], 'Bilgelik Evi anlamına gelen Beytülhikme, Abbasi Devleti\'nin başkenti Bağdat\'ta kurulmuştur.'),
  ('Bağdat\'ta temelleri Harun Reşid döneminde atılan Beytülhikme\'yi kurumsallaştırarak en parlak dönemine ulaştıran Abbasi halifesi kimdir?', 'Memun', ['Mansur', 'Muaviye', 'Mutasım'], 'Halife Memun (813-833) saray kütüphanesini gözlemevi, çeviri bürosu ve akademiyi kapsayan tam teşekküllü bir Beytülhikme\'ye dönüştürmüştür.'),
  ('"Beytülhikme" kavramının Türkçedeki tam karşılığı aşağıdakilerden hangisidir?', 'Bilgelik Evi', ['Yıldızlar Sarayı', 'Hükümdar Medresesi', 'Kitaplar Hazinesi'], 'Arapça "beyt" (ev) ve "hikme" (bilgelik/felsefe) kelimelerinden oluşan tamlama "Bilgelik Evi" anlamına gelir.'),
  ('1258 yılında Bağdat\'ı ele geçirerek Beytülhikme dahil olmak üzere şehirdeki kütüphaneleri tahrip eden Moğol hükümdarı kimdir?', 'Hülagü Han', ['Cengiz Han', 'Timur', 'Batu Han'], 'İlhanlı Devleti\'nin kurucusu Hülagü Han, 1258\'de Bağdat\'ı istila ederek Abbasi Halifeliği\'ne ve asırlık kütüphanelere son vermiştir.'),
  ('Büyük Selçuklu Devleti döneminde kurumsallaşmış medrese sisteminin öncüsü sayılan Nizamiye Medreseleri hangi vezirin adıyla anılır?', 'Nizamülmülk', ['Amidülmülk Kündürî', 'Sahib bin Abbad', 'Reşîdüddin Fazlullah'], 'Büyük Selçuklu Veziri Nizamülmülk (Hasan bin Ali et-Tûsî), imparatorluğun çeşitli kentlerinde kendi adıyla anılan Nizamiye Medreselerini kurmuştur.'),
  ('En ünlüsü 1067 yılında Bağdat\'ta açılan Nizamiye Medreseleri hangi Türk-İslam devleti zamanında inşa edilmiştir?', 'Büyük Selçuklu Devleti', ['Karahanlı Devleti', 'Gazneli Devleti', 'Harzemşahlar Devleti'], 'Nizamiye Medreseleri, Sultan Alp Arslan ve Sultan Melikşah dönemlerinde Büyük Selçuklu Devleti bünyesinde kurulmuştur.'),
  ('Bağdat Nizamiye Medresesi\'nde müderrislik (başhocalık) yapan ve "İhyâü Ulûmi\'d-Dîn" adlı eseriyle tanınan büyük İslam alimi kimdir?', 'Gazzâlî', ['İmam Matüridî', 'Fahreddin Râzî', 'Zemahşerî'], 'Hüccetü\'l-İslam unvanlı Ebû Hâmid el-Gazzâlî, 1091 yılında Nizamülmülk tarafından Bağdat Nizamiye Medresesi başmüderrisliğine atanmıştır.'),
  ('15. yüzyılda Semerkant\'ta büyük bir medrese ve gözlemevi kurarak şehri dönemin bilim merkezine dönüştüren Timurlu hükümdarı kimdir?', 'Uluğ Bey', ['Şahruh Mirza', 'Hüseyin Baykara', 'Babür Şah'], 'Timur\'un torunu olan Uluğ Bey, hükümdarlığının yanı sıra bizzat matematik ve astronomi çalışmaları yürüterek Semerkant\'ı bilim başkenti yapmıştır.'),
  ('Uluğ Bey Medresesi sembolik mimarisiyle bugün Özbekistan\'ın Semerkant şehrindeki hangi tarihi meydanda yer almaktadır?', 'Registan Meydanı', ['Nakş-ı Cihan Meydanı', 'Sultanahmet Meydanı', 'Tahrir Meydanı'], '1417-1420 yılları arasında inşa edilen Uluğ Bey Medresesi, Şirdar ve Tillakârî medreseleriyle birlikte ünlü Registan Meydanı\'nı çevreler.'),
  ('Semerkant\'ta Uluğ Bey\'in yanında yetişen ve daha sonra Fatih Sultan Mehmed\'in davetiyle İstanbul\'a gelerek medresede ders veren ünlü astronom kimdir?', 'Ali Kuşçu', ['Takiyüddin', 'Piri Reis', 'Seydi Ali Reis'], 'Uluğ Bey\'in "evladım" diye hitap ettiği öğrencisi ve rasathane müdürü Ali Kuşçu, Semerkant matematik-astronomi birikimini İstanbul\'a taşımıştır.'),
  ('Osmanlı Devleti\'nde ilk medrese 1331 yılında hangi padişah döneminde ve hangi şehirde kurulmuştur?', 'Orhan Gazi döneminde İznik\'te', ['Osman Gazi döneminde Söğüt\'te', 'I. Murad döneminde Edirne\'de', 'Yıldırım Bayezid döneminde Bursa\'da'], 'Osmanlı\'nın ilk medresesi İznik\'in fethinin ardından 1331\'de Orhan Gazi tarafından İznik\'te açılmıştır.'),
  ('İstanbul\'un fethinden sonra Fatih Sultan Mehmed tarafından Fatih Külliyesi bünyesinde kurulan ünlü yükseköğretim medreselerinin adı nedir?', 'Sahn-ı Seman Medreseleri', ['Enderun-ı Hümayun', 'Nizamiye Medreseleri', 'Galatasaray Sultanisi'], 'Fatih Camii\'nin iki yanında sekiz yüksek medrese olarak tasarlanan kuruma Sahn-ı Seman (Sekizli Avlu/Düzlük Medreseleri) adı verilmiştir.'),
  ('"Sahn-ı Seman" adlandırmasındaki "Seman" sözcüğü bu medreselerin hangi özelliğini ifade etmektedir?', 'Fatih Camii\'nin doğu ve batısında yer alan sekiz ana yüksek medreseden oluşmasını', ['Eğitim süresinin kesintisiz olarak seksen yıl devam etmesini', 'Yalnızca gökyüzü ve astronomi araştırmaları için tahsis edilmesini', 'Sekiz farklı yabancı dilde tercüme bürosu olarak çalışmasını'], 'Arapça "seman" (sekiz) kelimesi, caminin Karadeniz ve Akdeniz yönlerine simetrik dizilmiş sekiz büyük medreseyi ifade eder.'),
  ('16. yüzyılda Kanuni Sultan Süleyman tarafından İstanbul\'da inşa ettirilen ve Osmanlı medrese teşkilatının zirvesini oluşturan külliye hangisidir?', 'Süleymaniye Külliyesi', ['Selimiye Külliyesi', 'Şehzadebaşı Külliyesi', 'Sultanahmet Külliyesi'], '1550-1557 yılları arasında inşa edilen Süleymaniye Külliyesi, medreseleriyle Osmanlı eğitim piramidinin en üst basamağına yerleşmiştir.'),
  ('Süleymaniye Camii ve çevresindeki medreseleri arazinin eğimine ustalıkla yerleştirerek inşa eden büyük Osmanlı mimarı kimdir?', 'Mimar Sinan', ['Mimar Hayreddin', 'Mimar Kemaleddin', 'Sedefkâr Mehmed Ağa'], 'Hassa Başmimarı Koca Sinan, Haliç\'e bakan dik yamacı kademeli teraslarla değerlendirerek Süleymaniye Külliyesi ve medreselerini inşa etmiştir.'),
  ('Osmanlı Devleti\'nde Arap harfleriyle Türkçe kitap basan ilk matbaayı 1727 yılında İstanbul\'da kuran düşünür ve girişimci kimdir?', 'İbrahim Müteferrika', ['Yirmisekiz Mehmed Çelebi', 'Humbaracı Ahmed Paşa', 'Nedim'], 'Macaristan\'ın Kolozsvár kentinde doğup Osmanlı hizmetine giren İbrahim Müteferrika, Yirmisekizçelebizâde Said Efendi ile ilk Türk matbaasını kurmuştur.'),
  ('İbrahim Müteferrika Matbaası, Osmanlı Devleti\'nde Batı\'ya açılma ve kültür yenilikleriyle tanınan hangi dönemde kurulmuştur?', 'Lale Devri', ['Tanzimat Dönemi', 'Nizam-ı Cedid Dönemi', 'Meşrutiyet Dönemi'], 'Matbaa, Padişah III. Ahmed ve Sadrazam Nevşehirli Damat İbrahim Paşa\'nın yönetimde olduğu Lale Devri\'nde (1718-1730) açılmıştır.'),
  ('1729 yılında İbrahim Müteferrika Matbaası\'nda basılan ilk kitap aşağıdakilerden hangisidir?', 'Vankulu Lügati', ['Cihannümâ', 'Târîh-i Naîmâ', 'Divânu Lügâti\'t-Türk'], 'Cevherî\'nin es-Sıhâh adlı Arapça sözlüğünün Mehmed bin Mustafa el-Vânî (Vankulu) tarafından yapılan Türkçe tercümesi olan Vankulu Lügati ilk basılan eserdir.'),
  ('Tarih boyunca kurulan büyük kütüphaneler ve medreselerin hükümdarlar tarafından desteklenmesinin devletler açısından sağladığı ortak fayda nedir?', 'Nitelikli yönetici ve bilgin yetiştirerek devletin hem idari gücünü hem de kültürel saygınlığını artırması', ['Komşu devletlerle yapılan tüm sınır savaşlarını diplomasiye gerek kalmadan sona erdirmesi', 'Tarımsal üretime duyulan ihtiyacı tamamen ortadan kaldırarak ekonomiyi vergisiz yaşatması', 'Ülke içindeki tüm yerel dilleri ve lehçeleri birkaç yıl içinde tamamen unutturması'], 'Asurbanipal\'den Ptolemaioslara, Nizamülmülk\'ten Fatih ve Kanuni\'ye kadar tüm hükümdarlar bilgi kurumlarıyla bürokratik kapasiteyi ve siyasi meşruiyeti güçlendirmiştir.'),
  ('Batı dünyasında 1088 yılında kurularak en eski sürekli eğitim veren üniversite kabul edilen kurum hangi İtalyan şehrindedir?', 'Bologna', ['Floransa Üniversitesi', 'Padova Üniversitesi', 'Salerno Tıp Okulu'], '1088 yılında kurulan Bologna Üniversitesi, Batı dünyasının kesintisiz eğitim veren ilk üniversitesi kabul edilir.'),
  ('Fas\'ın Fes şehrinde 859 yılında Fatıma el-Fihri tarafından kurulan ve yükseköğretim tarihinin en eski kurumlarından sayılan medrese hangisidir?', 'Karaviyyin', ['El-Ezher Medresesi', 'Nizamiye Medresesi', 'Mustansıriye Medresesi'], 'Karaviyyin Camii ve Medresesi 859 yılında Fes\'te Fatıma el-Fihri tarafından kurulmuştur.'),
  ('Mısır\'ın Kahire şehrinde Fatımiler döneminde 970 yılı civarında kurulan ünlü İslam ilimleri ve yükseköğretim kurumu hangisidir?', 'El-Ezher', ['Beytülhikme', 'Sahn-ı Seman', 'Süleymaniye Medresesi'], 'El-Ezher, Fatımiler tarafından Kahire\'de cami ve ilim merkezi olarak inşa edilmiştir.'),
  ('İngilizce konuşulan dünyanın en eski üniversitesi olma özelliğini taşıyan ve 11. yüzyılın sonlarında eğitim faaliyetleri başlayan kurum hangisidir?', 'Oxford Üniversitesi', ['Cambridge Üniversitesi', 'Edinburgh Üniversitesi', 'Dublin Trinity Koleji'], 'Oxford Üniversitesi\'nde 1096 yılı civarında ders verilmeye başlanmış olup İngilizce konuşulan dünyanın en eski üniversitesidir.'),
  ('Orta Çağ\'da özellikle ilahiyat ve felsefe alanındaki çalışmalarıyla Avrupa\'nın en etkili merkezlerinden biri haline gelen Fransız üniversitesi hangisidir?', 'Paris Üniversitesi', ['Montpellier Üniversitesi', 'Toulouse Üniversitesi', 'Orleans Üniversitesi'], 'Paris Üniversitesi (Sorbonne geleneği), Orta Çağ\'da skolastik felsefe ve teolojinin en önemli merkeziydi.'),
  ('1167 yılında İngiltere Kralı II. Henry\'nin İngiliz öğrencilerin hangi yabancı şehirde öğrenim görmesini yasaklaması Oxford Üniversitesi\'nin hızla büyümesini sağlamıştır?', 'Paris', ['Bologna', 'Kahire', 'Kurtuba'], 'II. Henry\'nin Fransa ile yaşadığı siyasi gerilim sonucu İngiliz öğrencileri Paris\'ten geri çağırması Oxford\'un gelişimini hızlandırmıştır.'),
  ('Osmanlı Devleti\'nde Batı tarzında açılan ilk askeri teknik okul olarak 1734\'te Üsküdar\'da kurulan kurum aşağıdakilerden hangisidir?', 'Hendesehane', ['Tıbhane-i Amire', 'Mekteb-i Mülkiye', 'Darülmuallimin'], 'I. Mahmud döneminde Humbaracı Ahmed Paşa\'nın katkılarıyla 1734\'te Üsküdar\'da açılan Hendesehane, Batı tarzı ilk askeri teknik okuldur.'),
  ('1734 yılında Üsküdar\'da açılan Hendesehane\'nin kurulmasında başrol oynayan ve Müslüman olduktan sonra Humbaracı Ahmed Paşa adını alan Fransız uzman kimdir?', 'Comte de Bonneval', ['Baron de Tott', 'François Kauffer', 'Antoine Juchereau'], 'Claude Alexandre Comte de Bonneval, Osmanlı hizmetine girerek Humbaracı Ahmed Paşa adını almış ve Hendesehane\'nin kuruluşuna öncülük etmiştir.'),
  ('Osmanlı Devleti\'nde modern anlamda tıp eğitimi vermek amacıyla 14 Mart 1827\'de hangi padişah döneminde Tıbhane-i Amire açılmıştır?', 'II. Mahmud', ['III. Selim', 'Sultan Abdülmecid', 'II. Abdülhamid'], 'Yeniçeri Ocağı\'nın kaldırılmasının ardından ordunun hekim ihtiyacını karşılamak üzere II. Mahmud döneminde 14 Mart 1827\'de Tıbhane-i Amire kurulmuştur.'),
  ('Tanzimat Dönemi\'nde modern mülki idare amirleri (kaymakam, mutasarrıf vb.) ve bürokrat yetiştirmek amacıyla 1859 yılında kurulan okul hangisidir?', 'Mekteb-i Mülkiye', ['Mekteb-i Harbiye', 'Sanayi-i Nefise Mektebi', 'Hendese-i Mülkiye'], 'Mekteb-i Mülkiye, Sultan Abdülmecid döneminde 1859 yılında sivil idareci yetiştirmek üzere İstanbul\'da kurulmuştur.'),
  ('1859\'da İstanbul\'da kurulan Mekteb-i Mülkiye, Cumhuriyet döneminde 1936 yılında Ankara\'ya taşınarak hangi fakültenin temelini oluşturmuştur?', 'Ankara Üniversitesi Siyasal Bilgiler Fakültesi', ['İstanbul Üniversitesi Hukuk Fakültesi', 'Orta Doğu Teknik Üniversitesi İktisadi ve İdari Bilimler Fakültesi', 'Gazi Üniversitesi Eğitim Fakültesi'], 'Mekteb-i Mülkiye, 1936\'da Siyasal Bilgiler Okulu adıyla Ankara\'ya nakledilmiş, 1950\'de Ankara Üniversitesi Siyasal Bilgiler Fakültesi olmuştur.'),
  ('Sultan Abdülaziz döneminde 1 Eylül 1868\'de Fransız eğitim modeli örnek alınarak farklı din ve milletlerden öğrencilere karma eğitim vermek üzere açılan lise düzeyindeki kurum hangisidir?', 'Mekteb-i Sultani', ['Darüşşafaka Lisesi', 'Kabataş Mekteb-i İdadisi', 'Vefa İdadisi'], '1868\'de açılan Mekteb-i Sultani (Galatasaray Sultanisi), Türkçe ve Fransızca eğitim veren modern ortaöğretimin öncüsü olmuştur.'),
  ('Osmanlı Devleti\'nde medrese dışında Batılı anlamda kurulmaya çalışılan ilk üniversite kurumuna verilen ad aşağıdakilerden hangisidir?', 'Darülfünun', ['Enderun Mektebi', 'Sahn-ı Seman', 'Darülkurra'], '"Fenler Evi" anlamına gelen Darülfünun, Osmanlı\'nın modern üniversite kurma girişimlerine verilen isimdir.'),
  ('Cumhuriyet döneminde eğitim ve öğretimde birliği sağlayan Tevhid-i Tedrisat Kanunu hangi tarihte Türkiye Büyük Millet Meclisi\'nde kabul edilmiştir?', '3 Mart 1924', ['1 Kasım 1928', '12 Nisan 1931', '31 Mayıs 1933'], '430 sayılı Tevhid-i Tedrisat Kanunu, 3 Mart 1924 tarihinde kabul edilerek yürürlüğe girmiştir.'),
  ('3 Mart 1924 tarihli Tevhid-i Tedrisat Kanunu ile Türkiye\'deki bütün bilim ve öğretim kurumları hangi bakanlığa bağlanmıştır?', 'Maarif Vekaleti (Milli Eğitim Bakanlığı)', ['Şer\'iye ve Evkaf Vekaleti', 'Dahiliye Vekaleti (İçişleri Bakanlığı)', 'Adliye Vekaleti (Adalet Bakanlığı)'], 'Tevhid-i Tedrisat Kanunu ile ülkedeki tüm eğitim kurumları Maarif Vekaleti çatısı altında birleştirilmiştir.'),
  ('Türkiye Cumhuriyeti\'nde Yeni Türk Harflerinin Kabul ve Tatbiki Hakkında Kanun hangi tarihte TBMM tarafından kabul edilmiştir?', '1 Kasım 1928', ['3 Mart 1924', '24 Kasım 1928', '15 Nisan 1931'], '1353 sayılı Yeni Türk Harflerinin Kabul ve Tatbiki Hakkında Kanun, 1 Kasım 1928\'de kabul edilmiştir.'),
  ('Harf İnkılabı\'nın ardından okuma yazma seferberliği başlatmak ve yetişkin vatandaşlara yeni harfleri öğretmek amacıyla 1928 sonunda açılan kurum hangisidir?', 'Millet Mektepleri', ['Halkevleri', 'Köy Enstitüleri', 'İttihat Mektepleri'], 'Yeni harflerin geniş halk kitlelerine hızla öğretilmesi için 1928 yılı sonunda Millet Mektepleri teşkilatı kurulmuştur.'),
  ('24 Kasım 1928\'de yayımlanan Millet Mektepleri Talimatnamesi ile Mustafa Kemal Paşa\'ya verilen ve Öğretmenler Günü\'ne kaynaklık eden unvan nedir?', 'Başöğretmen', ['Mareşal', 'Gazi', 'Onursal Profesör'], 'Bakanlar Kurulu kararı ve Millet Mektepleri Talimatnamesi ile 24 Kasım 1928\'de Mustafa Kemal Paşa\'ya Millet Mektepleri Başöğretmenliği unvanı verilmiştir.'),
  ('Türk tarihini bilimsel yöntemlerle araştırmak ve İslam öncesi dönem dahil milli tarih bilincini geliştirmek amacıyla 1931 yılında kurulan kurumun ilk adı nedir?', 'Türk Tarihi Tetkik Cemiyeti', ['Türk Tarih Encümeni', 'Anadolu Medeniyetleri Enstitüsü', 'Şarkiyat Araştırmaları Kurumu'], 'Atatürk\'ün direktifiyle 12/15 Nisan 1931\'de Türk Tarihi Tetkik Cemiyeti kurulmuş, 1935\'te Türk Tarih Kurumu adını almıştır.'),
  ('Türkçenin öz güzelliğini ve zenginliğini ortaya çıkarmak amacıyla 12 Temmuz 1932\'de Atatürk\'ün talimatıyla kurulan kurumun ilk adı nedir?', 'Türk Dili Tetkik Cemiyeti', ['Dil ve Tarih-Coğrafya Heyeti', 'Encümen-i Edebiyat', 'Türk Lehçeleri Enstitüsü'], '12 Temmuz 1932\'de kurulan Türk Dili Tetkik Cemiyeti, 1936 yılındaki kurultayda Türk Dil Kurumu adını almıştır.'),
  ('1933 Üniversite Reformu sonucunda 31 Mayıs 1933 tarihli ve 2252 sayılı kanunla lağvedilen İstanbul Darülfünunu\'nun yerine 1 Ağustos 1933\'te hangi kurum açılmıştır?', 'İstanbul Üniversitesi', ['Ankara Üniversitesi', 'İstanbul Teknik Üniversitesi', 'Boğaziçi Üniversitesi'], '2252 sayılı kanunla İstanbul Darülfünunu kapatılmış ve yerine 1 Ağustos 1933 itibarıyla İstanbul Üniversitesi kurulmuştur.'),
  ('Türk Tarih Kurumu tarafından Ocak 1937\'den itibaren yayımlanmaya başlanan ve adını bizzat Atatürk\'ün koyduğu köklü bilimsel tarih dergisi hangisidir?', 'Belleten', ['Türkiyat Mecmuası', 'Ülkü Dergisi', 'Tarih-i Osmani Mecmuası'], 'Atatürk\'ün isim babası olduğu Belleten dergisi, 1937 yılından beri Türk Tarih Kurumu tarafından kesintisiz yayımlanan akademik yayındır.'),
  ('Osmanlı Devleti\'nde deniz subayı ve gemi inşa mühendisi yetiştirmek üzere 1775\'teki Hendesehane temelinde gelişen kurum III. Selim döneminde hangi adı almıştır?', 'Mühendishane-i Bahri-i Hümayun', ['Mühendishane-i Berri-i Hümayun', 'Mekteb-i Fünun-ı Harbiye', 'Tersane-i Amire Mektebi'], 'Deniz mühendishanesi, III. Selim dönemindeki düzenlemelerle Mühendishane-i Bahri-i Hümayun adını almış ve Deniz Harp Okulu ile İTÜ\'nün tarihsel köklerini oluşturmuştur.'),
  ('III. Selim döneminde Nizam-ı Cedid ıslahatları kapsamında 1795 yılında kara ordusuna topçu ve istihkâm subayı yetiştirmek üzere açılan okul hangisidir?', 'Mühendishane-i Berri-i Hümayun', ['Hendesehane-i Mülkiye', 'Mekteb-i Ulum-ı Edebiye', 'Enderun-ı Hümayun'], '1795\'te Hasköy\'de açılan Mühendishane-i Berri-i Hümayun, kara mühendislik eğitiminin ve İstanbul Teknik Üniversitesi\'nin öncülüdür.'),
  ('1908\'de II. Meşrutiyet\'in ilanından sonra Harbiye Nezareti olarak kullanılan Beyazıt\'taki eski Seraskerlik binası, Cumhuriyet\'in ilk yıllarında hangi yükseköğretim kurumuna devredilmiştir?', 'İstanbul Darülfünunu', ['Mekteb-i Mülkiye', 'Galatasaray Sultanisi', 'Yüksek Mühendis Mektebi'], 'Başkent Ankara\'ya taşınınca Beyazıt\'taki eski Harbiye Nezareti (Serasker Kapısı) 1923-1924\'te İstanbul Darülfünunu\'na tahsis edilmiştir.'),
  ('Orta Çağ\'da Bologna, Paris ve Oxford\'da doğan üniversite geleneğinin modern dünyaya bıraktığı akademik unvan ve ritüeller arasında aşağıdakilerden hangisi yer alır?', 'Rektör, dekan, bakalorya/lisans, doktora dereceleri ve cübbe giyme törenleri', ['Yalnızca askeri rütbeler olan mareşal, amiral ve tuğgeneral unvanları', 'Lonca çıraklığından ustalığa geçişte yapılan şed kuşatma törenleri', 'Olimpiyat oyunlarındaki meşale taşıma ve defne çelengi takma geleneği'], 'Günümüz üniversitelerindeki fakülte, dekan, rektör, lisans/doktora aşamaları ve akademik cübbe Orta Çağ Avrupa üniversite loncalarından miras kalmıştır.'),
  ('Cumhuriyet döneminde Millet Mekteplerinin ardından halk eğitimini ve kültür-sanat çalışmalarını yurt çapında yaymak amacıyla 19 Şubat 1932\'de Türk Ocakları\'nın kapanması sonrası açılan kurum hangisidir?', 'Halkevleri', ['Enderun Odaları', 'Encümen-i Daniş Şubeleri', 'Darülbedayi Salonları'], '19 Şubat 1932\'de 14 merkezde açılan Halkevleri; dil, tarih, edebiyat, güzel sanatlar, köycülük ve kütüphane kollarıyla Cumhuriyet\'in yaygın eğitim ve kültür kurumu olmuştur.'),
];
